// ¿Cuánto tarda buscar un cliente por código? Array con find contra Map.
function medir(f) { const t = performance.now(); const r = f(); return [performance.now() - t, r]; }

const CONSULTAS = 500;
for (const n of [1000, 10000, 100000]) {
  const clientes = [];
  for (let i = 0; i < n; i++) clientes.push({ id: "C" + i, nombre: "cliente " + i });

  const ids = [];
  for (let i = 0; i < CONSULTAS; i++) ids.push("C" + ((i * 7919) % n));

  const [tLista] = medir(() => { let c = 0; for (const id of ids) if (clientes.find(x => x.id === id)) c++; return c; });
  const [tArmar, mapa] = medir(() => new Map(clientes.map(c => [c.id, c])));
  const [tMapa] = medir(() => { let c = 0; for (const id of ids) if (mapa.get(id)) c++; return c; });

  console.log(`n=${n}: find ${tLista.toFixed(1)} ms | armar el Map ${tArmar.toFixed(1)} ms | consultar el Map ${tMapa.toFixed(2)} ms`);
}

class Monticulo {                       // mínimo arriba, guardado en un array
  constructor() { this.a = []; }
  meter(x) {
    const a = this.a; a.push(x);
    let i = a.length - 1;
    while (i > 0) {                      // sube mientras sea menor que su padre
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  sacar() {
    const a = this.a, top = a[0], ult = a.pop();
    if (a.length) {
      a[0] = ult; let i = 0;
      for (;;) {                         // baja mientras tenga un hijo menor
        let m = i; const l = 2 * i + 1, r = l + 1;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

// La cola arranca con N envíos; después, 2N pasos de «entra uno, sale el más urgente».
function conMonticulo(N, azar) {
  const h = new Monticulo();
  for (let i = 0; i < N; i++) h.meter(azar());
  let suma = 0;
  for (let i = 0; i < 2 * N; i++) { h.meter(azar()); suma += h.sacar(); }
  return suma;
}

function conArrayYMinimo(N, azar) {     // la alternativa: array desordenado y buscar el mínimo
  const a = [];
  for (let i = 0; i < N; i++) a.push(azar());
  let suma = 0;
  for (let i = 0; i < 2 * N; i++) {
    a.push(azar());
    let m = 0;
    for (let j = 1; j < a.length; j++) if (a[j] < a[m]) m = j;
    suma += a[m]; a[m] = a[a.length - 1]; a.pop();
  }
  return suma;
}
